def evolve(state: str, offsets: list[int], t: int) -> str:
    if t == 0:
        return state

    n = len(state)
    mask = (1 << n) - 1
    value = int(state, 2)
    shifts = [offset % n for offset in offsets]

    while t:
        if t & 1:
            updated = 0
            for shift in shifts:
                updated ^= ((value << shift) & mask) | (
                    value >> (n - shift)
                )
            value = updated

        t >>= 1
        # Over XOR, squaring the update doubles every offset.
        shifts = [(2 * shift) % n for shift in shifts]

    return format(value, f"0{n}b")
